"use strict";
// Generators the island owns: the program's loop must step them one value at
// a time, so the island's own console output interleaves with the loop's.
exports.naturals = function* (limit) {
  for (let i = 0; i < limit; i++) {
    console.log("island", i);
    yield i;
  }
};
exports.counted = function* (limit) {
  try {
    for (let i = 0; i < limit; i++) yield i;
  } finally {
    console.log("closed");
  }
};
exports.throwsLater = function* () {
  yield 1;
  throw new Error("boom");
};
exports.pairs = function* () {
  yield ["a", 1];
  yield ["b", 2];
  yield ["c", 3];
};
exports.boxed = {
  count: 0,
  *values() {
    for (const word of ["x", "y"]) {
      exports.boxed.count++;
      yield word;
    }
  },
};
// A generator with a typed input channel: each next(value) reaches it.
exports.echo = function* () {
  let got = yield "ready";
  while (got < 3) got = yield `got ${got}`;
  console.log("  [island] echo ends on", got);
};
